import{_ as n}from"./plugin-vue_export-helper-c27b6911.js";import{o as s,c as a,f as t}from"./app-36705845.js";const e={},p=t(`<h1 id="函数内联-inlining" tabindex="-1"><a class="header-anchor" href="#函数内联-inlining" aria-hidden="true">#</a> 函数内联（Inlining）</h1><p>函数内联是一种代码重构技术，它可以减少函数调用的开销，提高程序的运行效率。函数内联的原理是将函数调用处的代码替换为被调用函数的实现代码。函数内联的优点是可以减少函数调用的开销，缺点是会增加代码的体积。</p><h2 id="直观感受函数内联" tabindex="-1"><a class="header-anchor" href="#直观感受函数内联" aria-hidden="true">#</a> 直观感受函数内联</h2><p>函数调用并不便宜：要保存现场、跳转、执行函数体、再恢复现场。如果被调函数只有一两行，这笔「过路费」可能比函数本身还贵。内联就是把调用点直接替换成函数体，省掉来回折腾。</p><p>假设有：</p><div class="language-cpp line-numbers-mode" data-ext="cpp"><pre class="language-cpp"><code><span class="token keyword">inline</span> <span class="token keyword">int</span> <span class="token function">square</span><span class="token punctuation">(</span><span class="token keyword">int</span> x<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> x <span class="token operator">*</span> x<span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">int</span> <span class="token function">sum_of_squares</span><span class="token punctuation">(</span><span class="token keyword">int</span> a<span class="token punctuation">,</span> <span class="token keyword">int</span> b<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token function">square</span><span class="token punctuation">(</span>a<span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token function">square</span><span class="token punctuation">(</span>b<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>内联之后，逻辑上等价于：</p><div class="language-cpp line-numbers-mode" data-ext="cpp"><pre class="language-cpp"><code><span class="token keyword">int</span> <span class="token function">sum_of_squares</span><span class="token punctuation">(</span><span class="token keyword">int</span> a<span class="token punctuation">,</span> <span class="token keyword">int</span> b<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">(</span>a <span class="token operator">*</span> a<span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token punctuation">(</span>b <span class="token operator">*</span> b<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>调用消失了，编译器还能在此基础上继续做常量传播、死代码消除等优化。这也是为什么 C++ 里小函数常写成 <code>inline</code>——不是让人手动复制粘贴，而是给编译器一个「可以考虑内联」的提示。</p><h2 id="递归函数的内联" tabindex="-1"><a class="header-anchor" href="#递归函数的内联" aria-hidden="true">#</a> 递归函数的内联</h2><p>递归函数能不能内联？能，但通常只内联<strong>有限次</strong>。</p><div class="language-cpp line-numbers-mode" data-ext="cpp"><pre class="language-cpp"><code><span class="token keyword">int</span> <span class="token function">factorial</span><span class="token punctuation">(</span><span class="token keyword">int</span> n<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>n <span class="token operator">&lt;=</span> <span class="token number">1</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token number">1</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> n <span class="token operator">*</span> <span class="token function">factorial</span><span class="token punctuation">(</span>n <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">int</span> <span class="token function">f5</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token function">factorial</span><span class="token punctuation">(</span><span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果编译器在编译 <code>f5</code> 时能看到 <code>factorial(5)</code> 的实参是常量 5，就可能做<strong>递归内联（recursive inlining）</strong>：一层层展开，直到变成：</p><div class="language-cpp line-numbers-mode" data-ext="cpp"><pre class="language-cpp"><code><span class="token keyword">int</span> <span class="token function">f5</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token number">5</span> <span class="token operator">*</span> <span class="token number">4</span> <span class="token operator">*</span> <span class="token number">3</span> <span class="token operator">*</span> <span class="token number">2</span> <span class="token operator">*</span> <span class="token number">1</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>这本质上是一种<strong>部分求值</strong>。但无限递归没法全展开，所以编译器会设深度上限。尾递归有时还能被优化成循环，那就不是内联，而是另一种变换。</p><h2 id="我们应该在哪个阶段进行函数内联" tabindex="-1"><a class="header-anchor" href="#我们应该在哪个阶段进行函数内联" aria-hidden="true">#</a> 我们应该在哪个阶段进行函数内联？</h2><p>内联通常发生在<strong>中端优化</strong>阶段，也就是 IR 生成之后、代码生成之前。典型流程：</p><ol><li><strong>前端</strong>：把函数调用翻译成 IR 里的 <code>call</code> 指令</li><li><strong>中端</strong>：分析调用关系，决定哪些 <code>call</code> 展开成被调函数的 IR 块</li><li><strong>后端</strong>：对内联后的代码做寄存器分配、指令选择</li></ol><p>也可以在更早或更晚做，但各有取舍：</p><table><thead><tr><th>阶段</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>中端（主流）</td><td>内联后还能跑 SSA、常量传播、死代码消除等 IR 级优化</td><td>需要维护 IR 的正确性</td></tr><tr><td>后端</td><td>能看到目标平台特性</td><td>优化窗口变窄，代码体积更难控制</td></tr><tr><td>链接期（LTO）</td><td>跨翻译单元内联，突破 <code>.cpp</code> 文件边界</td><td>编译时间显著增加</td></tr></tbody></table><p>实践中，GCC/LLVM 都在中端做主要内联，再配合 LTO 做跨模块内联。</p><h2 id="如何判断一个函数调用是否应该内联" tabindex="-1"><a class="header-anchor" href="#如何判断一个函数调用是否应该内联" aria-hidden="true">#</a> 如何判断一个函数调用是否应该内联？</h2><p>内联不是越多越好——代码膨胀会导致指令缓存失效率上升。编译器一般用一组启发式规则做权衡：</p><p><strong>倾向于内联：</strong></p><ul><li>函数体很小（几条指令）</li><li>调用点在热路径上（循环内、频繁调用）</li><li>实参是常量，内联后能触发常量折叠</li><li>函数只被一处调用（<code>static</code>、匿名命名空间、<code>always_inline</code>）</li><li>内联能消除不可达分支（比如 <code>if (false)</code> 的调试代码）</li></ul><p><strong>倾向于不内联：</strong></p><ul><li>函数体很大，或含复杂控制流</li><li>函数地址被取走（<code>&amp;func</code>），需要保留符号</li><li>递归深度未知或可能很深</li><li>虚函数调用，目标在编译期不确定（去虚化后才能内联）</li><li>内联后代码体积增长超过阈值</li></ul><p>现代编译器还会用<strong>收益模型（cost model）</strong>：估算内联节省的调用开销，对比代码体积增长，净收益为正才内联。当然有些属性如 <code>__attribute__((always_inline))</code> 和 <code>__attribute__((noinline))</code> 可以人为覆盖默认决策。</p>`,28),o=[p];function c(i,l){return s(),a("div",null,o)}const d=n(e,[["render",c],["__file","(5)函数内联.html.vue"]]);export{d as default};
